const secret = $json.headers && $json.headers['x-mnemo-secret'];
if (secret !== 'n8n-webhook-secret-2024') { throw new Error('unauthorized'); }
const p = $json.body;
if (!p || !Array.isArray(p.entries) || p.entries.length === 0) { throw new Error('payload invalido'); }
return p.entries.map(e => {
  const key = e.key || (e.metadata && e.metadata.file_path) || ('entry-' + Date.now() + '-' + Math.random().toString(36).slice(2,8));
  // key dentro do metadata -> o DELETE do upsert (metadata->>'key') passa a funcionar e re-runs sao idempotentes
  const metadata = Object.assign({}, e.metadata || {}, { key });
  return { json: {
    namespace: p.namespace || '/memory/faturas',
    source_agent: p.source_agent || 'n8n-intake',
    key,
    content: e.content,
    metadata
  }};
});

const items = $input.all();
let srcs = [];
try { srcs = $('Parse and Auth').all().map(i => i.json); } catch (e) {}
if (items.length !== srcs.length) throw new Error('desalinhamento embed/entradas: ' + items.length + ' vs ' + srcs.length);
const out = [];
for (let i = 0; i < items.length; i++) {
  const emb = items[i].json;
  const src = srcs[i];
  let embArr;
  if (Array.isArray(emb)) embArr = emb;
  else if (emb && Array.isArray(emb.data) && emb.data[0] && Array.isArray(emb.data[0].embedding)) embArr = emb.data[0].embedding;
  else if (emb && Array.isArray(emb.embeddings) && Array.isArray(emb.embeddings[0])) embArr = emb.embeddings[0];
  else throw new Error('resposta do embed inesperada [' + i + ']: ' + JSON.stringify(emb).slice(0, 120));
  const meta = Object.assign({}, src.metadata, { key: src.key });
  out.push({ json: Object.assign({}, src, {
    embedding: JSON.stringify(embArr),
    params: [src.namespace, src.key, JSON.stringify(embArr), src.content, JSON.stringify(meta), src.source_agent]
  }) });
}
return out;

